CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, language text NOT NULL DEFAULT 'ar', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY profile_own ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.stores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL DEFAULT 'متجري', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,UPDATE ON public.stores TO authenticated; GRANT ALL ON public.stores TO service_role; ALTER TABLE public.stores ENABLE ROW LEVEL SECURITY; CREATE POLICY store_own ON public.stores FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'owner', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,store_id)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY roles_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid REFERENCES public.stores(id) ON DELETE CASCADE, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY products_demo ON public.products FOR SELECT TO anon,authenticated USING(store_id IS NULL); CREATE POLICY products_owner ON public.products FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.stores s WHERE s.id=store_id AND s.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.stores s WHERE s.id=store_id AND s.owner_id=auth.uid()));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid REFERENCES public.stores(id) ON DELETE CASCADE, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.orders TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY orders_demo ON public.orders FOR SELECT TO anon,authenticated USING(store_id IS NULL); CREATE POLICY orders_owner ON public.orders FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.stores s WHERE s.id=store_id AND s.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.stores s WHERE s.id=store_id AND s.owner_id=auth.uid()));
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER stores_updated BEFORE UPDATE ON public.stores FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER roles_updated BEFORE UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER products_updated BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER orders_updated BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE FUNCTION public.setup_merchant() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); INSERT INTO public.stores(owner_id) VALUES(NEW.id) RETURNING id INTO sid; INSERT INTO public.user_roles(user_id,store_id,role) VALUES(NEW.id,sid,'owner'); RETURN NEW; END $$; CREATE TRIGGER merchant_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.setup_merchant();
